function validate([tiles, carpetLen]) {
  if (!Array.isArray(tiles) || tiles.length < 1 || tiles.length > 50000) return 'tiles needs 1 to 50,000 ranges.';
  for (const t of tiles) {
    if (!Array.isArray(t) || t.length !== 2 || !t.every(Number.isInteger)) return 'Each range is a pair [l, r] of integers.';
    if (t[0] < 1 || t[0] > t[1] || t[1] > 1e9) return 'Each range needs 1 <= l <= r <= 10^9.';
  }
  if (!Number.isInteger(carpetLen) || carpetLen < 1 || carpetLen > 1e9) return 'carpetLen is an integer from 1 to 10^9.';
  const sorted = tiles.map(t => t).sort((a, b) => a[0] - b[0]);
  for (let i = 1; i < sorted.length; i++) if (sorted[i][0] <= sorted[i - 1][1]) return 'The ranges in tiles must not overlap.';
  return null;
}

