function maximumWhiteTiles(tiles, carpetLen) {
  tiles.sort((a, b) => a[0] - b[0]);
  let best = 0;
  let covered = 0;
  let right = 0;
  for (let left = 0; left < tiles.length; left++) {
    const carpetEnd = tiles[left][0] + carpetLen - 1;
    while (right < tiles.length && tiles[right][1] <= carpetEnd) {
      covered += tiles[right][1] - tiles[right][0] + 1;
      right++;
    }
    let partial = 0;
    if (right < tiles.length && tiles[right][0] <= carpetEnd) {
      partial = carpetEnd - tiles[right][0] + 1;
    }
    best = Math.max(best, covered + partial);
    if (right > left) {
      covered -= tiles[left][1] - tiles[left][0] + 1;
    } else {
      right++;
    }
  }
  return best;
}

