function maximumWhiteTiles(tiles, carpetLen) {
  // Try the carpet starting at every range's left end and ending at every range's right end,
  // and intersect it with every range.
  const starts = [];
  for (const [l, r] of tiles) starts.push(l, r - carpetLen + 1);
  let most = 0;
  for (const s of starts) {
    const e = s + carpetLen - 1;
    let white = 0;
    for (const [l, r] of tiles) {
      const lo = Math.max(l, s), hi = Math.min(r, e);
      if (lo <= hi) white += hi - lo + 1;
    }
    if (white > most) most = white;
  }
  return most;
}

