function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 6);
  const maxGap = large ? 200000 : int(0, 4);
  const maxLength = large ? 250000 : int(1, 6);
  const tiles = [];
  let next = int(1, large ? 1000 : 4);
  for (let i = 0; i < n; i++) {
    const l = next;
    const r = l + int(0, maxLength - 1);
    tiles.push([l, r]);
    next = r + 1 + int(0, maxGap);
  }
  // The input may list the ranges in any order.
  for (let i = tiles.length - 1; i > 0; i--) {
    const j = int(0, i);
    [tiles[i], tiles[j]] = [tiles[j], tiles[i]];
  }
  const span = tiles.reduce((m, t) => Math.max(m, t[1]), 0);
  const carpetLen = large ? (rand() < 0.2 ? int(1, 1000000000) : int(1, 3000000)) : int(1, span + 2);
  return [tiles, carpetLen];
}
